218	const ICONS: Record<IconKey, (p: { size?: number; className?: string }) => React.ReactElement> = {
219	  bolt: IconBolt,
220	  apps: IconApps,
221	  terminal: IconTerminal,
222	  shield: IconShield,
223	  gauge: IconGauge,
224	  users: IconUsers,
225	  backup: IconBackup,
226	  globe: IconGlobe,
227	  scale: IconScale,
228	};
229	
230	export function ReasonIcon({ icon, size = 20, className }: { icon: IconKey; size?: number; className?: string }) {
231	  const C = ICONS[icon];
232	  return <C size={size} className={className} />;
233	}
234	
235	/** Compact gold 5-star row (matches the existing ReviewCarousel star treatment). */
236	export function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
237	  const filled = Math.max(0, Math.min(5, rating));
238	  return (
239	    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
240	      <span className="text-amber-300">{"★".repeat(filled)}</span>
241	      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
242	    </span>
243	  );
244	}
