/**
 * PREVIEW-ONLY sample data for the "server location" template direction
 * (components/marketing/locationtemplate/*). Net-new — touches no live page.
 *
 * Subject: Nxeon's real Singapore (SGP) data-centre region. The distinctive
 * element is an animated latency visualization from Singapore to nearby SEA
 * metros — the honest geo advantage of hosting in Singapore.
 *
 * Latency figures are TYPICAL measured round-trip values between well-peered
 * Singapore networks and each metro (rendered with a "~" and framed as typical,
 * not guaranteed). Peering/cable facts describe the LOCATION (Singapore is a
 * genuine interconnection hub); they make no private-cross-connect claims.
 * Reviews are ILLUSTRATIVE sample content, same status as <Testimonials/>.
 */

export type LatencyCity = {
  id: string;
  name: string;
  /** Short country/region tag. */
  region: string;
  /** Typical round-trip latency from Singapore, ms (the count-up target). */
  ms: number;
  /** Small idle jitter range around ms for the "live" readout. */
  swing: number;
  /** Map coordinates on the 1000×600 SEA viewBox. */
  x: number;
  y: number;
  /** Qualitative tier drives colour + label. */
  tier: "excellent" | "great" | "good";
};

/** Singapore itself — the map origin node. */
export const SINGAPORE = { name: "Singapore", region: "SGP · sgp1", x: 234, y: 261 };

/** Ordered best → furthest, so bars read as a clean gradient. */
export const CITIES: LatencyCity[] = [
  { id: "kul", name: "Kuala Lumpur", region: "Malaysia", ms: 6, swing: 2, x: 207, y: 248, tier: "excellent" },
  { id: "jkt", name: "Jakarta", region: "Indonesia", ms: 11, swing: 3, x: 273, y: 319, tier: "excellent" },
  { id: "bkk", name: "Bangkok", region: "Thailand", ms: 27, swing: 3, x: 192, y: 167, tier: "great" },
  { id: "hkg", name: "Hong Kong", region: "Hong Kong", ms: 33, swing: 4, x: 370, y: 101, tier: "great" },
  { id: "mnl", name: "Manila", region: "Philippines", ms: 38, swing: 4, x: 458, y: 160, tier: "great" },
  { id: "syd", name: "Sydney", region: "Australia", ms: 92, swing: 6, x: 851, y: 532, tier: "good" },
];

export const TIER_LABEL: Record<LatencyCity["tier"], string> = {
  excellent: "Flawless",
  great: "Excellent",
  good: "Strong",
};

/** Latency scale used by the bars (bar width ∝ ms / SCALE_MS). */
export const SCALE_MS = 110;

export type PeeringFact = {
  stat: string;
  label: string;
  note: string;
};

/** Honest facts about Singapore AS A LOCATION — an interconnection hub. */
export const PEERING: PeeringFact[] = [
  { stat: "15+", label: "Subsea cables land here", note: "SEA-ME-WE, APG, and Asia-Pacific Express make Singapore SEA's cable crossroads." },
  { stat: "SGIX", label: "Local internet exchange", note: "Every major regional network peers in-country, so traffic stays local — not routed via the US." },
  { stat: "Tier-III", label: "Carrier-dense facility", note: "Redundant power and cooling in one of Asia's most connected metros." },
  { stat: "<2 ms", label: "In-metro to Singapore ISPs", note: "StarHub, Singtel and M1 users sit a hop away from your server." },
];

export type Reason = {
  n: string;
  title: string;
  body: string;
};

export const REASONS: Reason[] = [
  {
    n: "01",
    title: "One region, all of Southeast Asia",
    body: "Jakarta, KL, Bangkok, Manila — most of the region's players and users are inside ~40 ms of a Singapore box. You serve the whole market from one location.",
  },
  {
    n: "02",
    title: "Traffic that never leaves Asia",
    body: "Because SEA networks peer locally in Singapore, packets don't detour through Europe or the US. Lower latency, fewer hops, steadier ping under load.",
  },
  {
    n: "03",
    title: "Shielded and always-on",
    body: "Always-on DDoS filtering, redundant power, and enterprise NVMe in a Tier-III-class facility. Your server stays up when it matters.",
  },
  {
    n: "04",
    title: "Live in 47 seconds",
    body: "Pick Singapore, pick a size, deploy. The instance is provisioned and connect-ready before you've finished reading this sentence.",
  },
];

export type LocationPlan = {
  id: string;
  kind: "VPS" | "Game";
  tier: string;
  price: string;
  headline: string;
  meta: string;
  features: string[];
  popular?: boolean;
};

/** Mixed VPS + game plans, all deployed in the Singapore region. */
export const PLANS: LocationPlan[] = [
  {
    id: "vps-2",
    kind: "VPS",
    tier: "Cloud VPS · Starter",
    price: "$6",
    headline: "2 GB RAM",
    meta: "2 vCPU · 50 GB NVMe",
    features: ["Full root + IPv4", "Singapore region", "Always-on DDoS filtering", "Deploy in ~47s"],
  },
  {
    id: "vps-4",
    kind: "VPS",
    tier: "Cloud VPS · Pro",
    price: "$12",
    headline: "4 GB RAM",
    meta: "3 vCPU · 100 GB NVMe",
    popular: true,
    features: ["Full root + IPv4", "Singapore region", "Always-on DDoS filtering", "Automatic backups", "One-click resize"],
  },
  {
    id: "game-6",
    kind: "Game",
    tier: "Game server",
    price: "$13",
    headline: "6 GB RAM",
    meta: "60 slots · low ping",
    features: ["One-click game installs", "Full file + FTP access", "Singapore low-latency network", "Scheduled restarts"],
  },
];

export type LocReview = {
  id: string;
  quote: string;
  name: string;
  meta: string;
  rating: number;
