export const REVIEWS: LocReview[] = [
  { id: "l1", quote: "Ping from Jakarta is single digits. Our players stopped complaining about lag the day we moved to Singapore.", name: "Rizky A.", meta: "Community server, Indonesia", rating: 5 },
  { id: "l2", quote: "We serve customers across Malaysia and Thailand from one Singapore VPS. Latency is genuinely great everywhere.", name: "Wei Lin", meta: "SaaS founder, KL", rating: 5 },
  { id: "l3", quote: "Deployed in Singapore in under a minute and the route to Sydney is cleaner than the AU hosts we tried.", name: "Marcus T.", meta: "Co-op host, AU/NZ", rating: 5 },
];

export const RATING_AVG = "4.9";
export const RATING_LABEL = "Trusted across Southeast Asia";

"use client";

/**
 * SEA LATENCY MAP — the location template's signature visual.
 *
 * A regional, Singapore-centred take on the shipped <NetworkMap/>: SEA landmass
 * rendered as deterministic dot clusters (SSR-safe, no assets), Singapore as a
 * pulsing origin node, and brand-gradient arcs to six nearby metros. Each arc
 * carries a travelling "ping" pulse and each city node shows a LIVE latency
 * readout that counts up on first view and idles with small jitter — telling the
 * "low-latency across Asia" story with real numbers, not a spinning globe.
 *
 * All motion is disabled under prefers-reduced-motion (inline <style> guard +
 * the shared kit hooks resolve to their resting values). Net-new, preview-only.
 */

import { CITIES, SINGAPORE, type LatencyCity } from "./data";
import { usePrefersReducedMotion, useInViewOnce, useCountUp, useJitter } from "@/components/marketing/gamelanding/kit";

const W = 1000;
const H = 600;

/* SEA landmass footprints on the viewBox (decorative, equirectangular-ish). */
const LAND: { cx: number; cy: number; rx: number; ry: number }[] = [
  { cx: 205, cy: 150, rx: 135, ry: 110 }, // mainland SEA (Thailand/Vietnam/Cambodia)
  { cx: 350, cy: 60, rx: 170, ry: 70 }, // south China coast + Hong Kong
  { cx: 224, cy: 250, rx: 34, ry: 90 }, // Malay peninsula
  { cx: 205, cy: 312, rx: 78, ry: 34 }, // Sumatra
  { cx: 322, cy: 292, rx: 72, ry: 60 }, // Borneo
  { cx: 300, cy: 348, rx: 96, ry: 22 }, // Java
  { cx: 452, cy: 178, rx: 46, ry: 74 }, // Philippines
  { cx: 860, cy: 540, rx: 140, ry: 96 }, // Australia (NE)
];

const noise = (i: number, j: number) => {
  const s = Math.sin(i * 12.9898 + j * 78.233) * 43758.5453;
  return s - Math.floor(s);
};

function landDots() {
  const dots: { x: number; y: number; o: number }[] = [];
  const step = 14;
  for (let x = step; x < W; x += step) {
    for (let y = 24; y < H - 16; y += step) {
      let best = 2;
      for (const c of LAND) {
        const t = ((x - c.cx) / c.rx) ** 2 + ((y - c.cy) / c.ry) ** 2;
        if (t < best) best = t;
      }
      const n = noise(x, y);
      if (best < 0.9 || (best < 1 && n > 0.55)) {
        dots.push({ x: x + (n - 0.5) * 4, y: y + (noise(y, x) - 0.5) * 4, o: 0.2 + (1 - best) * 0.28 });
      }
    }
  }
  return dots;
}

const arcPath = (a: { x: number; y: number }, b: { x: number; y: number }) => {
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2 - Math.hypot(a.x - b.x, a.y - b.y) * 0.24;
  return `M${a.x},${a.y} Q${mx},${my} ${b.x},${b.y}`;
};

const TIER_COLOR: Record<LatencyCity["tier"], string> = {
  excellent: "#22d3ee",
  great: "#3b82f6",
  good: "#8a70fb",
};

export function SeaLatencyMap() {
  const dots = landDots();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();

  return (
    <div
      ref={ref}
      className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-950/70 glow-brand"
    >
      <style>{`
        @keyframes lat-pulse { 0%{offset-distance:0%;opacity:0} 10%{opacity:1} 85%{opacity:1} 100%{offset-distance:100%;opacity:0} }
        @keyframes lat-blip { 0%,100%{opacity:.55;r:3} 50%{opacity:1;r:3.6} }
        @keyframes lat-ring { 0%{transform:scale(.6);opacity:.55} 100%{transform:scale(1.9);opacity:0} }
        @media (prefers-reduced-motion: reduce){
          .lat-pulse,.lat-blip,.lat-ring{animation:none!important}
          .lat-pulse{opacity:0}
        }
      `}</style>

      {/* header */}
      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5 font-mono text-[11px]">
        <span className="flex items-center gap-2 text-slate-400">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> nxeon · singapore edge
        </span>
        <span className="text-slate-500">live round-trip · 6 SEA metros</span>
      </div>

      <div className="relative">
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_28%_44%,rgba(34,211,238,0.12),transparent_62%)]"
        />
        <svg
          viewBox={`0 0 ${W} ${H}`}
          className="relative block w-full"
          role="img"
          aria-label="Latency from Nxeon Singapore to Kuala Lumpur, Jakarta, Bangkok, Hong Kong, Manila and Sydney"
        >
          <defs>
            <linearGradient id="lat-arc" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#22d3ee" />
              <stop offset="100%" stopColor="#8a70fb" />
            </linearGradient>
            <radialGradient id="lat-sg" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#67e8f9" />
              <stop offset="100%" stopColor="#22d3ee" />
            </radialGradient>
          </defs>

          {/* landmass dots */}
          {dots.map((d, i) => (
            <circle key={i} cx={d.x} cy={d.y} r={1.15} fill={`rgba(120,150,220,${d.o})`} />
          ))}

          {/* arcs + travelling ping pulses */}
          {CITIES.map((c, k) => {
            const d = arcPath(SINGAPORE, c);
            return (
              <g key={`arc-${c.id}`}>
                <path d={d} fill="none" stroke="url(#lat-arc)" strokeWidth="1.3" opacity="0.45" />
                <circle
                  className="lat-pulse"
                  r="3"
                  fill={TIER_COLOR[c.tier]}
                  style={{
                    offsetPath: `path('${d}')`,
                    animation: seen ? `lat-pulse ${2.6 + k * 0.28}s ${k * 0.32}s linear infinite` : "none",
                    opacity: 0,
                  }}
                />
              </g>
            );
          })}

          {/* city nodes with live readouts */}
          {CITIES.map((c) => (
            <CityNode key={c.id} city={c} active={seen} />
          ))}

          {/* Singapore origin node */}
          <g>
            <circle className="lat-ring" cx={SINGAPORE.x} cy={SINGAPORE.y} r="14" fill="none" stroke="#22d3ee" strokeWidth="1.5" style={{ transformOrigin: `${SINGAPORE.x}px ${SINGAPORE.y}px`, animation: seen ? "lat-ring 2.6s ease-out infinite" : "none" }} />
            <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r="16" fill="rgba(34,211,238,0.12)" />
            <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r="5.2" fill="url(#lat-sg)" />
            <g transform={`translate(${SINGAPORE.x - 4}, ${SINGAPORE.y + 16})`}>
              <rect x="0" y="0" width="118" height="22" rx="11" fill="rgba(6,10,20,0.92)" stroke="rgba(34,211,238,0.4)" />
              <circle cx="13" cy="11" r="3" fill="#22d3ee" />
              <text x="24" y="15" fontFamily="ui-monospace,monospace" fontSize="11" fontWeight="600" fill="#e2e8f0">
                Singapore · you
              </text>
            </g>
          </g>
        </svg>
      </div>
    </div>
  );
}

/* one city node — animated ms readout riding the map */
function CityNode({ city, active }: { city: LatencyCity; active: boolean }) {
  const reduced = usePrefersReducedMotion();
  const base = useCountUp(city.ms, active, 1200, reduced);
  const live = useJitter(city.ms, city.swing, active, 2200, reduced);
  const value = base < city.ms ? base : live; // count up, then idle-jitter
  const color = TIER_COLOR[city.tier];
  const labelW = city.name.length * 6.4 + 52;
  // keep labels inside the viewBox
  const flip = city.x + labelW + 16 > W;
  const lx = flip ? -labelW - 10 : 12;

  return (
    <g>
      <circle cx={city.x} cy={city.y} r="10" fill="rgba(34,211,238,0.08)" />
      <circle
        className="lat-blip"
        cx={city.x}
        cy={city.y}
        r="3"
        fill={color}
        style={{ animation: active && !reduced ? "lat-blip 2.4s ease-in-out infinite" : "none" }}
      />
      <g transform={`translate(${city.x + lx}, ${city.y - 11})`}>
        <rect x="0" y="0" width={labelW} height="22" rx="11" fill="rgba(6,10,20,0.9)" stroke="rgba(255,255,255,0.1)" />
        <text x="9" y="15" fontFamily="ui-monospace,monospace" fontSize="10.5" fill="#cbd5e1">
          {city.name}
        </text>
        <text
          x={labelW - 8}
          y="15"
          textAnchor="end"
          fontFamily="ui-monospace,monospace"
          fontSize="10.5"
          fontWeight="700"
          fill={color}
        >
          {value}ms
        </text>
      </g>
    </g>
  );
}

