/**
 * GHOST DEPLOY TERMINAL — the app-hosting template's hero centerpiece.
 *
 * A glass console that types the real ghost-cli install sequence (ssh → ghost
 * install → live) and resolves to "Ghost is live — 47s". Reuses the shared
 * preview typing hook so timing + reduced-motion behaviour match the game
 * directions. Net-new, preview-only; does not touch the shipped <DeployCard/>.
 */

import { DEPLOY_LINES } from "./data";
import { usePrefersReducedMotion, useInViewOnce, useTypedLines } from "@/components/marketing/gamelanding/kit";
import { GhostMark } from "./GhostMark";

export function GhostDeployTerminal() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const { done, current, caret } = useTypedLines(DEPLOY_LINES, seen, reduced);

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div
        className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#070c17]/90 backdrop-blur-xl"
        style={{ boxShadow: "0 40px 120px -50px rgba(111,71,245,0.55), 0 0 0 1px rgba(255,255,255,0.04)" }}
      >
        {/* ambient glow */}
        <div
          className="pointer-events-none absolute -inset-24 -z-0 opacity-70"
          style={{ background: "radial-gradient(40% 40% at 85% 0%, rgba(34,211,238,0.22), transparent 70%)" }}
          aria-hidden
        />

        {/* header */}
        <div className="relative flex items-center gap-2.5 border-b border-white/[0.07] bg-white/[0.02] px-4 py-3">
          <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
          <span className="ml-2 inline-flex items-center gap-2 font-mono text-[11px] uppercase tracking-widest text-slate-500">
            <GhostMark size={14} /> ghost · install
          </span>
          <span className="ml-auto rounded-md border border-accent-cyan/30 bg-accent-cyan/10 px-2 py-0.5 font-mono text-[10px] text-accent-cyan">
            47s
          </span>
        </div>

        {/* stream */}
        <div className="relative min-h-[236px] space-y-1.5 p-5 font-mono text-[12.5px] leading-relaxed">
          {done.map((l, i) => {
            const isCmd = l.startsWith("$");
            const isOk = l.startsWith("✓");
            return (
              <div key={i} className={isOk ? "font-semibold text-emerald-300" : isCmd ? "text-slate-200" : "text-slate-400"}>
                {isCmd ? (
                  <>
                    <span className="text-accent-cyan">$</span>
                    {l.slice(1)}
                  </>
                ) : (
                  l
                )}
              </div>
            );
          })}
          {caret < DEPLOY_LINES.length && (
            <div className="text-slate-300">
              {current}
              <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-slate-300 motion-safe:animate-blink" />
            </div>
          )}

          {/* live badge once finished */}
          {caret >= DEPLOY_LINES.length && (
            <div className="mt-3 flex items-center gap-2 rounded-lg border border-emerald-400/20 bg-emerald-400/[0.06] px-3 py-2 text-xs text-emerald-300">
              <span className="relative flex h-2 w-2">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400/70 motion-reduce:hidden" />
                <span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-400" />
              </span>
              yourblog.com is live · you own the data
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

